package com.glassbox.chess; import com.glassbox.chess.domain.*; import com.glassbox.chess.rule.*; import com.glassbox.chess.util.FenParser; import org.junit.jupiter.api.Test; import static org.junit.jupiter.api.Assertions.*; public class SpecialRulesTest{@Test void bothCastlesAreGenerated(){Board b=FenParser.parse("r3k2r/8/8/8/8/8/8/R3K2R w KQkq - 0 1");assertEquals(2,MoveValidator.getLegalMoves(b,Color.WHITE).stream().filter(m->m instanceof CastleMove).count());}@Test void enPassantIsGenerated(){Board b=FenParser.parse("7k/8/8/3pP3/8/8/8/4K3 w - d6 0 1");assertEquals(1,MoveValidator.getLegalMoves(b,Color.WHITE).stream().filter(m->m instanceof EnPassantMove).count());}@Test void allPromotionChoicesAreGenerated(){Board b=FenParser.parse("7k/P7/8/8/8/8/8/7K w - - 0 1");assertEquals(4,MoveValidator.getLegalMoves(b,Color.WHITE).stream().filter(m->m instanceof PromotionMove).count());}@Test void moveUndoRestoresStartingPosition(){Board b=new Board();b.setupInitialPosition();String before=b.getPositionKey();Move m=MoveValidator.getLegalMoves(b,Color.WHITE).get(0);b.applyMove(m);b.undoMove(m);assertEquals(before,b.getPositionKey());}}
